function findSecondLargest(nums) {
  let first = -Infinity;
  let second = -Infinity;
  for (const num of nums) {
    if (num > first) {
      second = first;
      first = num;
    } else if (num > second && num < first) {
      second = num;
    }
  }
  return second === -Infinity ? null : second;
}

